import type { InnerStoreOptions } from "./types";

// A special identifier within the store generated by createStore
export const _RESY_BRAND_ = Symbol.for("_resy_brand_");

// prefix for computed
export const _COMPUTED_PREFIX_ = "$";

/**
 * @description Segment separator of the proxy cache key built by `pathKey`.
 *
 * A control character is used so it cannot appear in an ordinary property name,
 * which keeps the encoded key readable while still allowing a collision-free
 * encoding. See `pathKey` in `./utils` for how it is applied.
 */
export const _PATH_KEY_SEPARATOR_ = "\u0001";

/**
 * @description Reverse map from a read-side wrapper (nested proxy or container
 * handle) back to the raw value it wraps.
 *
 * 🌟 Module-scoped rather than per store: being a wrapper is intrinsic to the
 * object, not to the store that created it. A wrapper read from store A can be
 * assigned into store B (`storeB.x = storeA.user`), and B still has to store
 * the raw object instead of A's proxy.
 */
export const _WRAPPER_ORIGIN_ = new WeakMap<object, unknown>();

export const DEFAULT_OPTIONS: InnerStoreOptions = {
  unmountRestore: true,
  namespace: undefined,
  immutable: undefined,
  _callerName_: "createStore",
};
